# ==============================================================================# 067_AGENT_EVIDENCE_ENGINE.py# IOTEC MISSION CORE# Todo agente deve provar o que fez.# ==============================================================================from __future__ import annotationsimport sqlite3import jsonimport socketfrom datetime import datetimefrom pathlib import PathDB = Path("iotec.db")class AgentEvidenceEngine:    def __init__(self):        self.conn = sqlite3.connect(DB)        self.conn.row_factory = sqlite3.Row        self.conn.execute("""        CREATE TABLE IF NOT EXISTS agent_evidence(            id INTEGER PRIMARY KEY AUTOINCREMENT,            timestamp TEXT,            agent TEXT,            mission TEXT,            status TEXT,            target TEXT,            evidence TEXT,            limitation TEXT,            suggestion TEXT,            progress REAL,            metadata TEXT,            hostname TEXT        )        """)        self.conn.commit()    # -------------------------------------------------------------------------    def publish(        self,        agent,        mission,        status,        target="",        evidence="",        limitation="",        suggestion="",        progress=0,        metadata=None,    ):        payload = {            "timestamp": datetime.utcnow().isoformat(),            "agent": agent,            "mission": mission,            "status": status,            "target": target,            "evidence": evidence,            "limitation": limitation,            "suggestion": suggestion,            "progress": progress,            "metadata": metadata or {},            "hostname": socket.gethostname(),        }        self.conn.execute(            """            INSERT INTO agent_evidence(                timestamp,                agent,                mission,                status,                target,                evidence,                limitation,                suggestion,                progress,                metadata,                hostname            )            VALUES(?,?,?,?,?,?,?,?,?,?,?)            """,            (                payload["timestamp"],                payload["agent"],                payload["mission"],                payload["status"],                payload["target"],                payload["evidence"],                payload["limitation"],                payload["suggestion"],                payload["progress"],                json.dumps(payload["metadata"], ensure_ascii=False),                payload["hostname"],            ),        )        self.conn.commit()        return payload# ==============================================================================# TESTE# ==============================================================================if __name__ == "__main__":    engine = AgentEvidenceEngine()    engine.publish(        agent="LEAD_HUNTER_01",        mission="Captar empresas de engenharia",        status="MISSION_STARTED",        target="Empresas de Engenharia",        progress=0,    )    engine.publish(        agent="LEAD_HUNTER_01",        mission="Captar empresas de engenharia",        status="MISSION_EVIDENCE",        evidence="Empresa XYZ localizada",        progress=25,        metadata={            "empresa": "Empresa XYZ",            "cidade": "Fortaleza",            "setor": "Engenharia"        }    )    engine.publish(        agent="LEAD_HUNTER_01",        mission="Captar empresas de engenharia",        status="MISSION_BLOCKED",        limitation="Sem integração com CRM",        suggestion="Adicionar integração REST",        progress=25,    )    print("AGENT_EVIDENCE_ENGINE ONLINE")